">// cCriticalSectionInit.h (Initialisation d'une section critique)</span><br><pre class="GCode1 Code1 AceCode" data-mode="c_cpp" data-theme="gruvbox" data-bg-color="transparent" style="background-color: transparent;">...
#pragma once

class cCriticalSectionInit
{
