    ~cCriticalSectionInit();
};
...</pre><br><span class="GText2" style="
color: #00ff00;
">// cCriticalSectionInit.cpp (Initialisation d'une section critique)</span><br><pre class="GCode1 Code1 AceCode" data-mode="c_cpp" data-theme="gruvbox" data-bg-color="transparent" style="background-color: transparent;">...
#include "cCriticalSectionInit.h"
#include "cCriticalSectionList.h"

cCriticalSectionInit::cCriticalSectionInit()
{
    cCriticalSectionList oCriticalSectionList;
    oCriticalSectionList.initAll();
}

cCriticalSectionInit::~cCriticalSectionInit()
{
    cCriticalSectionList oCriticalSectionList;
    oCriticalSectionList.deleteAll();
}
...</pre><br><span class="GText2" style="
color: #00ff00;
">// cCriticalSectionLock.h (Verrouillage d'une section critique)</span><br><pre class="GCode1 Code1 AceCode" data-mode="c_cpp" data-theme="gruvbox" data-bg-color="transparent" style="background-color: transparent;">...
#pragma once

#include "cCriticalSectionList.h"

class cCriticalSectionLock
{
public:
    cCriticalSectionLock(eCriticalSection _id);
    ~cCriticalSectionLock();
    bool isLocked() const;
    static bool isLocked(eCriticalSection _id);

private:
    eCriticalSection m_id;
};
...</pre><br><span class="GText2" style="
color: #00ff00;
">// cCriticalSectionLock.cpp (Verrouillage d'une section critique)</span><br><pre class="GCode1 Code1 AceCode" data-mode="c_cpp" data-theme="gruvbox" data-bg-color="transparent" style="background-color: transparent;">...
#include "cCriticalSectionLock.h"

cCriticalSectionLock::cCriticalSectionLock(eCriticalSection _id)
    : m_id(_id)
{
    cCriticalSectionList oCriticalSectionList;
    oCriticalSectionList.lock(m_id);
}

cCriticalSectionLock::~cCriticalSectionLock()
{
    cCriticalSectionList oCriticalSectionList;
    oCriticalSectionList.unlock(m_id);
}

bool cCriticalSectionLock::isLocked() const
{
    cCriticalSectionList oCriticalSectionList;
    return oCriticalSectionList.isLocked(m_id);
}

bool cCriticalSectionLock::isLocked(eCriticalSection _id)
{
    cCriticalSectionList oCriticalSectionList;
    return oCriticalSectionList.isLocked(_id);
}
